const body = $input.first().json.body ?? {};
const required = ['appointment_type', 'date', 'time'];
const missing = required.filter((field) => body[field] === undefined || body[field] === null || String(body[field]).trim() === '');
if (missing.length) throw new Error(`Missing required availability fields: ${missing.join(', ')}`);
const allowedTypes = ['new_patient_exam', 'routine_checkup', 'cleaning', 'tooth_pain_exam', 'cosmetic_consultation', 'follow_up', 'pediatric_visit'];
if (!allowedTypes.includes(String(body.appointment_type).toLowerCase())) throw new Error('Unsupported appointment_type.');
const allowedDentists = ['your_dentist_1', 'your_dentist_2', 'any available dentist'];
if (body.dentist_name !== undefined && !String(body.dentist_name).trim()) throw new Error('dentist_name cannot be blank when supplied.');
if (body.dentist_name && !allowedDentists.includes(String(body.dentist_name).trim().toLowerCase())) throw new Error('Unsupported dentist_name.');
return $input.all();

const body = $('Dental Availability Webhook').first().json.body ?? {};

const DENTISTS = ['YOUR_DENTIST_1', 'YOUR_DENTIST_2'];
const CLINIC_SLOTS = []; // REQUIRED: configure appointment times in HH:mm format.

function normalizeDate(value) {
  const text = String(value ?? '').trim();
  let match = text.match(/^(\d{4})-(\d{1,2})-(\d{1,2})$/);
  if (match) return `${match[1]}-${match[2].padStart(2, '0')}-${match[3].padStart(2, '0')}`;
  match = text.match(/^(\d{1,2})\/(\d{1,2})\/(\d{4})$/);
  if (match) return `${match[3]}-${match[1].padStart(2, '0')}-${match[2].padStart(2, '0')}`;
  return text;
}

function normalizeTime(value) {
  const text = String(value ?? '').trim().toUpperCase();
  const match = text.match(/^(\d{1,2})(?::(\d{2}))?\s*(AM|PM)?$/);
  if (!match) return text;
  let hour = Number(match[1]);
  const minute = Number(match[2] ?? 0);
  if (match[3] === 'AM' && hour === 12) hour = 0;
  if (match[3] === 'PM' && hour !== 12) hour += 12;
  return `${String(hour).padStart(2, '0')}:${String(minute).padStart(2, '0')}`;
}

const same = (a, b) => String(a ?? '').trim().toLowerCase() === String(b ?? '').trim().toLowerCase();
const rows = $input.all().map((item) => item.json);
const requestedDentist = String(body.dentist_name || 'Any available dentist').trim();
const appointmentType = String(body.appointment_type).trim();
const requestedDate = normalizeDate(body.date);
const requestedTime = normalizeTime(body.time);

function isConflict(dentist, date, time) {
  const rowConflict = rows.some((row) =>
    same(row.dentist_name, dentist) &&
    normalizeDate(row.appointment_date) === date &&
    normalizeTime(row.appointment_time) === time &&
    !['cancelled', 'canceled'].includes(String(row.status ?? 'confirmed').trim().toLowerCase())
  );
  return rowConflict;
}

const candidates = same(requestedDentist, 'Any available dentist') ? DENTISTS : [requestedDentist];
const selectedDentist = candidates.find((dentist) => !isConflict(dentist, requestedDate, requestedTime));
const validClinicTime = CLINIC_SLOTS.includes(requestedTime);

return [{ json: {
  available: Boolean(selectedDentist) && validClinicTime,
  requested_dentist: requestedDentist,
  dentist_name: selectedDentist || requestedDentist,
  appointment_type: appointmentType,
  requested_date: requestedDate,
  requested_time: requestedTime,
  date: requestedDate,
  time: requestedTime,
} }];

const request = $('Check Dentist Schedule').first().json;
const body = $('Dental Availability Webhook').first().json.body ?? {};
const rows = $('Load Dental Appointments').all().map((item) => item.json);

const DENTISTS = ['YOUR_DENTIST_1', 'YOUR_DENTIST_2'];
const CLINIC_SLOTS = []; // REQUIRED: configure appointment times in HH:mm format.

const same = (a, b) => String(a ?? '').trim().toLowerCase() === String(b ?? '').trim().toLowerCase();
const normalizeTime = (value) => {
  const text = String(value ?? '').trim().toUpperCase();
  const match = text.match(/^(\d{1,2})(?::(\d{2}))?\s*(AM|PM)?$/);
  if (!match) return text;
  let hour = Number(match[1]);
  if (match[3] === 'AM' && hour === 12) hour = 0;
  if (match[3] === 'PM' && hour !== 12) hour += 12;
  return `${String(hour).padStart(2, '0')}:${String(Number(match[2] ?? 0)).padStart(2, '0')}`;
};
const normalizeDate = (value) => String(value ?? '').trim();
const addDays = (date, count) => {
  const value = new Date(`${date}T12:00:00Z`);
  value.setUTCDate(value.getUTCDate() + count);
  return value.toISOString().slice(0, 10);
};
const isBusinessDay = (date) => {
  const day = new Date(`${date}T12:00:00Z`).getUTCDay();
  const BUSINESS_DAYS = []; // REQUIRED: configure open weekdays (0 = Sunday, 6 = Saturday).
  return BUSINESS_DAYS.includes(day);
};
const isConflict = (dentist, date, time) => {
  const rowConflict = rows.some((row) =>
    same(row.dentist_name, dentist) &&
    normalizeDate(row.appointment_date) === date &&
    normalizeTime(row.appointment_time) === time &&
    !['cancelled', 'canceled'].includes(String(row.status ?? 'confirmed').trim().toLowerCase())
  );
  return rowConflict;
};

const requestedDentist = request.requested_dentist;
const dentists = same(requestedDentist, 'Any available dentist') ? DENTISTS : [requestedDentist];
const alternatives = [];

// Prefer one later slot on the requested day.
for (const time of CLINIC_SLOTS.filter((slot) => slot > request.requested_time)) {
  const dentist = dentists.find((name) => !isConflict(name, request.requested_date, time));
  if (dentist) {
    alternatives.push({ date: request.requested_date, time, dentist_name: dentist });
    break;
  }
}

// Then offer the first verified slot on the next available business day.
for (let offset = 1; offset <= 7 && alternatives.length < 2; offset++) {
  const date = addDays(request.requested_date, offset);
  if (!isBusinessDay(date)) continue;
  let found = false;
  for (const time of CLINIC_SLOTS) {
    const dentist = dentists.find((name) => !isConflict(name, date, time));
    if (dentist) {
      alternatives.push({ date, time, dentist_name: dentist });
      found = true;
      break;
    }
  }
  if (found) break;
}

return [{ json: {
  available: false,
  requested_dentist: requestedDentist,
  dentist_name: requestedDentist,
  appointment_type: String(body.appointment_type ?? request.appointment_type),
  requested_date: request.requested_date,
  requested_time: request.requested_time,
  alternative_slots: alternatives,
} }];

const data = $input.first().json;
const readable = data.alternative_slots.map((slot) => `${slot.date} at ${slot.time} with ${slot.dentist_name}`);
const message = readable.length
  ? `${data.dentist_name} is not available on ${data.requested_date} at ${data.requested_time}. Verified alternatives: ${readable.join(' or ')}.`
  : `${data.dentist_name} is not available on ${data.requested_date} at ${data.requested_time}, and no nearby alternative was found. Offer a human callback.`;
return [{ json: { ...data, message } }];

const body = $input.first().json.body ?? {};
const required = ['patient_name', 'phone_number', 'patient_type', 'appointment_type', 'date', 'time', 'visit_reason'];
const missing = required.filter((field) => body[field] === undefined || body[field] === null || String(body[field]).trim() === '');
if (missing.length) throw new Error(`Missing required appointment fields: ${missing.join(', ')}`);
if (!['new_patient', 'existing_patient'].includes(String(body.patient_type).toLowerCase())) throw new Error('patient_type must be new_patient or existing_patient.');
const allowedTypes = ['new_patient_exam', 'routine_checkup', 'cleaning', 'tooth_pain_exam', 'cosmetic_consultation', 'follow_up', 'pediatric_visit'];
if (!allowedTypes.includes(String(body.appointment_type).toLowerCase())) throw new Error('Unsupported appointment_type.');
const allowedDentists = ['your_dentist_1', 'your_dentist_2', 'any available dentist'];
if (body.dentist_name && !allowedDentists.includes(String(body.dentist_name).trim().toLowerCase())) throw new Error('Unsupported dentist_name.');
if (body.caller_confirmed !== true) throw new Error('Appointment booking requires explicit caller confirmation.');
return $input.all();

const body = $input.first().json.body ?? {};
const action = String(body.action ?? '').toLowerCase();
if (!['cancel', 'reschedule'].includes(action)) throw new Error('action must be cancel or reschedule.');
if (!body.appointment_id || !body.phone_number) throw new Error('appointment_id and phone_number are required.');
if (body.caller_confirmed !== true) throw new Error('Appointment changes require explicit caller confirmation.');
if (action === 'reschedule' && (!body.new_date || !body.new_time)) throw new Error('new_date and new_time are required for rescheduling.');
const allowedTypes = ['new_patient_exam', 'routine_checkup', 'cleaning', 'tooth_pain_exam', 'cosmetic_consultation', 'follow_up', 'pediatric_visit'];
if (body.new_appointment_type && !allowedTypes.includes(String(body.new_appointment_type).toLowerCase())) throw new Error('Unsupported new_appointment_type.');
const allowedDentists = ['your_dentist_1', 'your_dentist_2', 'any available dentist'];
if (body.new_dentist_name && !allowedDentists.includes(String(body.new_dentist_name).trim().toLowerCase())) throw new Error('Unsupported new_dentist_name.');
return $input.all();

const body = $('Dental Manage Webhook').first().json.body ?? {};
const normalizePhone = (value) => {
  const digits = String(value ?? '').replace(/\D/g, '');
  return digits.length > 10 ? digits.slice(-10) : digits;
};
const appointmentId = String(body.appointment_id ?? '').trim().toUpperCase();
const phone = normalizePhone(body.phone_number);
if (!appointmentId || !phone) return [{ json: { found: false, error: 'appointment_id or phone_number is missing' } }];
const match = $input.all().find(({ json }) =>
  String(json.appointment_id ?? '').trim().toUpperCase() === appointmentId &&
  normalizePhone(json.phone_number) === phone &&
  !['cancelled', 'canceled'].includes(String(json.status ?? '').trim().toLowerCase())
);
if (!match) return [{ json: { found: false } }];
return [{ json: { ...match.json, found: true, row_number: match.json.row_number } }];

const body = $('Dental Manage Webhook').first().json.body ?? {};
const original = $input.first().json;
const hasValue = (value) => value !== undefined && value !== null && String(value).trim() !== '';
return [{ json: {
  row_number: original.row_number,
  appointment_id: original.appointment_id,
  appointment_date: hasValue(body.new_date) ? body.new_date : original.appointment_date,
  appointment_time: hasValue(body.new_time) ? body.new_time : original.appointment_time,
  dentist_name: hasValue(body.new_dentist_name) ? body.new_dentist_name : original.dentist_name,
  appointment_type: hasValue(body.new_appointment_type) ? body.new_appointment_type : original.appointment_type,
  status: 'confirmed',
} }];

const body = $input.first().json.body ?? {};
const required = ['patient_name', 'phone_number', 'reason'];
const missing = required.filter((field) => body[field] === undefined || body[field] === null || String(body[field]).trim() === '');
if (missing.length) throw new Error(`Missing required callback fields: ${missing.join(', ')}`);
return $input.all();
